COMMENT ON COLUMN lock_deprecation_warning.effective_at IS '锁定时刻记录的弃用生效时刻（UTC）';
COMMENT ON COLUMN lock_deprecation_warning.reason IS '锁定时刻记录的弃用说明，NULL 表示原窗口未填写';

CREATE UNIQUE INDEX IF NOT EXISTS uk_warning_lock_name ON lock_deprecation_warning (lock_file_id, name);

CREATE TABLE IF NOT EXISTS idempotent_request (
    request_id     VARCHAR(64)  NOT NULL PRIMARY KEY,
    operation      VARCHAR(32)  NOT NULL,
    request_hash   VARCHAR(64)  NOT NULL,
