        super(422, "DEPRECATION_VIOLATION",
                "依赖闭包含 " + violations.size() + " 个已生效弃用版本，无法锁定");
        this.violations = List.copyOf(violations);
    }

    public List<DeprecationViolationView> getViolations() {
        return violations;
    }
}

